		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"死亡后最多2日以内会出现思念体，第一个思念体拥有比较明确的意识，但很盲目的追从一个目标。\n\n\t\t\t\t该目标是会受到死亡前体验的刺激性情景和内容影响，但这仅仅是推测，实际需要测试。\n\n\t\t\t\t第一个思念体的话与生存时的模样几乎一样很难分辨，而且实验体的目标意识越强，形象越清晰。" 
		}
	},
	[8095] = {
